Y = []
import re
for i in y:
    # Extract the last number from the BI-RADS string
    match = re.search(r'(\d+)', i)
    if match:
        Y.append(int(match.group(1)))
    else:
        # Fallback: try to get the last character if it's a digit
        if i[-1].isdigit():
            Y.append(int(i[-1]))
        else:
            Y.append(0)  # Default value if no number found
